// Smart Fit dictionary (task 14), shared by the customer app, admin and the server's error messages.
// uz (Latin) is the default; ru is the second language. Keys are namespaced: common, kiosk (customer app), adm (admin), staff (staff app),
// cat/gender (one label set for both pages), err/field (server error codes). Every key must exist in both languages
// (test/i18n.test.js). A plural value is { one, few, many } picked by Intl.PluralRules; uz has no plural forms.
// Importing this module touches no DOM, so the server can use it too.

