  'land.foot.city': 'Toshkentda hozir',
  'land.nav.mall': 'Savdo markazi',
  'land.nav.shop': "Do'kon",
  'land.nav.plans': 'Tariflar',
  'land.doc_title': "Savdo markazlari va kiyim do'konlari uchun kiosk-stilist",
  'land.hero.title': "Savdo markazi va kiyim do'koni uchun kiosk-stilist",
  'land.hero.lead': "Mijoz bo'yi va vaznini kiritadi, Smart Fit esa bugungi ob-havoga mos obrazlarni faqat javonda bor kiyimlardan tuzadi: bitta do'konda yoki markazning hamma do'konlaridan.",
  'land.door.mall': 'Savdo markaziga nima beradi',
  'land.door.shop': "Do'konga nima beradi",
  'land.try_mall_phone': 'Markaz demosini telefonda oching',
  'land.try_mall_kiosk': "Markaz kioskini sinab ko'ring",
  'land.try_staff': 'Xodimlar ilovasiga kirish',
  'land.mall.kicker': 'Savdo markaziga',
  'land.mall.title': 'Bitta kiosk butun markaz uchun',
  'land.mall.lead': "Mehmon qaysi do'konga borishni bilmasa ham, kerakli kiyimni topadi. Har do'kon o'z mahsulotlari, narxlari va buyurtmalarini o'zi boshqaradi: markaz ularni ko'rmaydi.",
  'land.mall.shot': "Demo markaz telefonda: butun markazdan obraz, aksiyalar, qidiruv va do'konlar.",
  'land.mall.dir': "Do'konlar, qidiruv va qavatlar xaritasi",
  'land.mall.dir_c': "Kiosk yoki bitta QR orqali: do'konlar logotipi, qavati va kategoriyalari bilan, hozir ochiq yoki yopiqligi. Qidiruv markazning hamma do'konlaridagi bor kiyimlarni topadi. Xaritada qavat va do'kon belgisi, kiosk yonida «Siz shu yerdasiz».",
  'land.mall.cart': "Bitta savat, bir necha do'kon",
  'land.mall.cart_c': "Mijoz turli do'konlardan tanlaydi va bir marta rasmiylashtiradi: har do'konga alohida buyurtma, bitta raqam va bitta holat sahifasi. Pul aralashmaydi: har do'kon o'z kassasida oladi. «Butun markazdan obraz» ham shu savatga tushadi: imkon bo'lsa bir necha do'kondan, joy uchun hech kim pul to'lamaydi.",
  'land.mall.offers': 'Aksiyalar kutish ekranida',
  'land.mall.offers_c': "Do'kon aksiya yozadi, markaz tasdiqlaydi. Kiosk bo'sh turganda tasdiqlangan aksiyalar almashinib turadi, tartibi va vaqtini markaz belgilaydi. Har aksiya necha marta ko'rilgani va bosilgani sanaladi.",
  'land.mall.stats': 'Mehmonlar nimani qidiradi',
  'land.mall.stats_c': "Kun va soat bo'yicha tashriflar (kiosk va telefon alohida), qidirilgan so'zlar va hech bir do'konda topilmaganlari, do'kon va xarita ochilishlari, do'konlar reytingi, CSV. Faqat sonlar: telefon raqami, IP va rasm yozilmaydi.",
  'land.shop.kicker': "Do'konga",
  'land.shop.title': 'Mijozga razmer, sizga nazorat',
  'land.shop.lead': "Kiosk, mijozning telefoni, xodimlar ilovasi va egasining paneli bitta ombordan ishlaydi: qoldig'i yo'q kiyim taklif ham qilinmaydi, sotilmaydi ham.",
  'land.shop.fit': 'Obraz va razmer',
  'land.shop.fit_c': "Uchta obraz yoki faqat bitta kiyim: ob-havo, byudjet va «Qayerga kiyasiz?» bo'yicha, faqat mijoz razmerida bor narsadan. Razmer butun gavda yoki belgacha rasmdan, rasmsiz esa odatdagi razmer yoki santimetrdan. Bolaga bo'yidan, rasm so'ralmaydi. Rasm diskka, bazaga va loglarga yozilmaydi.",
  'land.shop.catalog': 'Katalog va kiyim sahifasi',
  'land.shop.catalog_c': "Kategoriyalar va razmer jadvali do'koningizniki. Kiyim sahifasida bor razmerlar, «Shu bilan yaxshi ketadi», xaridorlar bahosi va boshqa filialdagi qoldiq. Kiyimdagi QR yorliq shu sahifani mijoz telefonida ochadi.",
  'land.shop.cashier': 'Kassa',
  'land.shop.cashier_c': "Naqd, karta yoki kassada muddatli to'lov: oyiga qancha bo'lishini server hisoblaydi. Promo-kodlar va to'liq obrazga chegirma. Kun oxirida kassani yopish: to'lov usullari bo'yicha savdo va kassadagi naqd farqi.",
  'land.shop.staff': 'Xodimlar ilovasi',
  'land.shop.staff_c': "Telefonda: kabinaga so'rovlar, yig'iladigan buyurtmalar, qabul qilish va inventarizatsiya (QR, shtrix-kod yoki SKU, internet uzilsa ham), filiallar orasida ko'chirish. Sotuvchi o'z sotuvlari va komissiyasini ko'radi.",
  'land.shop.owner': 'Foyda va nazorat',
  'land.shop.owner_c': "Tannarx va foyda kun, kategoriya va kiyim bo'yicha; sotuvchilar komissiyasi; qaytarishlar va qoldiq yo'qligi sabab yo'qotilgan talab. Ikki bosqichli kirish, kirishlar tarixi va jamoa rollari.",
  'land.plans.title': 'Tariflar',
  'land.plans.trial': { one: "Yangi do'kon {n} kun {plan} tarifida sinab ko'radi. Narxni so'rang: biz qo'ng'iroq qilamiz.", few: "Yangi do'kon {n} kun {plan} tarifida sinab ko'radi. Narxni so'rang: biz qo'ng'iroq qilamiz.", many: "Yangi do'kon {n} kun {plan} tarifida sinab ko'radi. Narxni so'rang: biz qo'ng'iroq qilamiz." },
  'land.plans.grace': { one: "Muddat tugagach yana {n} kun ogohlantirish bilan ishlaydi, keyin panel faqat o'qish uchun ochiq, kiosk esa to'xtaydi. Hech narsa o'chirilmaydi.", few: "Muddat tugagach yana {n} kun ogohlantirish bilan ishlaydi, keyin panel faqat o'qish uchun ochiq, kiosk esa to'xtaydi. Hech narsa o'chirilmaydi.", many: "Muddat tugagach yana {n} kun ogohlantirish bilan ishlaydi, keyin panel faqat o'qish uchun ochiq, kiosk esa to'xtaydi. Hech narsa o'chirilmaydi." },
  'land.plans.keys': "AI stilist va AI bilan «O'zimda ko'rish» kalit ulanganda ishlaydi (pastda).",
  'land.plans.ask': "Narxni so'rang",
  'land.plans.trial_here': 'Sinov shu tarifda',
