  'land.nav.mall': 'Торговый центр',
  'land.nav.shop': 'Магазин',
  'land.nav.plans': 'Тарифы',
  'land.doc_title': 'Киоск-стилист для торговых центров и магазинов одежды',
  'land.hero.title': 'Киоск-стилист для торгового центра и магазина одежды',
  'land.hero.lead': 'Покупатель вводит рост и вес, а Smart Fit собирает образы по сегодняшней погоде только из того, что есть на полках: в одном магазине или во всех магазинах центра.',
  'land.door.mall': 'Что получает торговый центр',
  'land.door.shop': 'Что получает магазин',
  'land.try_mall_phone': 'Открыть демо центра на телефоне',
  'land.try_mall_kiosk': 'Попробовать киоск центра',
  'land.try_staff': 'Войти в приложение сотрудников',
  'land.mall.kicker': 'Торговому центру',
  'land.mall.title': 'Один киоск на весь центр',
  'land.mall.lead': 'Посетитель находит нужную вещь, даже если не знает, в какой магазин идти. Каждый магазин сам ведёт свои товары, цены и заказы: центр их не видит.',
  'land.mall.shot': 'Демо-центр на телефоне: образ со всего центра, акции, поиск и магазины.',
  'land.mall.dir': 'Магазины, поиск и карта этажей',
  'land.mall.dir_c': 'Через киоск или один QR: магазины с логотипом, этажом и категориями, открыт ли магазин сейчас. Поиск находит вещи в наличии во всех магазинах центра. На карте — этаж и метка магазина, у киоска — «Вы здесь».',
  'land.mall.cart': 'Одна корзина на несколько магазинов',
  'land.mall.cart_c': 'Покупатель выбирает в разных магазинах и оформляет один раз: каждому магазину свой заказ, один номер и одна страница статуса. Деньги не смешиваются: каждый магазин принимает оплату на своей кассе. «Образ со всего центра» тоже попадает в эту корзину: по возможности из нескольких магазинов, и место в нём не продаётся.',
  'land.mall.offers': 'Акции на экране ожидания',
  'land.mall.offers_c': 'Магазин пишет акцию, центр её одобряет. Пока киоск свободен, одобренные акции сменяют друг друга; порядок и время задаёт центр. Для каждой акции считаются показы и нажатия.',
  'land.mall.stats': 'Что ищут посетители',
  'land.mall.stats_c': 'Посещения по дням и часам (киоск и телефон отдельно), поисковые слова и те, что не нашлись ни в одном магазине, открытия магазинов и карты, рейтинг магазинов, CSV. Только числа: ни телефонов, ни IP, ни снимков.',
  'land.shop.kicker': 'Магазину',
  'land.shop.title': 'Покупателю — размер, вам — контроль',
  'land.shop.lead': 'Киоск, телефон покупателя, приложение сотрудников и панель владельца работают с одним складом: того, чего нет в наличии, не предлагают и не продают.',
  'land.shop.fit': 'Образ и размер',
  'land.shop.fit_c': 'Три образа или одна вещь: по погоде, бюджету и поводу, только из того, что есть в размере покупателя. Размер по снимку в полный рост или по пояс, без снимка — по привычному размеру или сантиметрам. Ребёнку — по росту, снимок не нужен. Снимок не пишется ни на диск, ни в базу, ни в логи.',
  'land.shop.catalog': 'Каталог и страница вещи',
  'land.shop.catalog_c': 'Категории и таблица размеров — ваши. На странице вещи: размеры в наличии, «С этим хорошо сочетается», оценки покупателей и остаток в другом филиале. QR-ярлык на вещи открывает эту страницу на телефоне покупателя.',
  'land.shop.cashier': 'Касса',
  'land.shop.cashier_c': 'Наличные, карта или рассрочка на кассе: сумму в месяц считает сервер. Промокоды и скидка за весь образ. В конце дня — закрытие кассы: продажи по способам оплаты и расхождение наличных.',
  'land.shop.staff': 'Приложение для сотрудников',
