// Colour names are product data typed by staff in Uzbek; the common ones read in Russian, anything else as typed.
const COLORS_RU = {
  qora: 'чёрный', oq: 'белый', kulrang: 'серый', "to'q ko'k": 'тёмно-синий', "ko'k": 'синий', bej: 'бежевый',
  jigarrang: 'коричневый', qizil: 'красный', yashil: 'зелёный', sariq: 'жёлтый', pushti: 'розовый', binafsha: 'фиолетовый',
  zaytun: 'оливковый', krem: 'кремовый', bordo: 'бордовый', havorang: 'голубой',
};
// Task 30, "Bor kiyimimga mos": what the customer already owns is picked from these fixed lists (no free text).
export const COLORS = Object.keys(COLORS_RU);
export const STYLES = ['classic', 'casual', 'sport'];

export const DICT = { uz, ru };
let current = 'uz';
export const getLang = () => current;

// Own keys only: request data such as a size named "constructor" must never reach Object.prototype.
const own = (lang, key) => (Object.hasOwn(DICT, lang) && Object.hasOwn(DICT[lang], key) ? DICT[lang][key] : undefined);
const fill = (s, vars) => s.replace(/\{(\w+)\}/g, (m, k) => (Object.hasOwn(vars, k) ? String(vars[k]) : m));

// t('kiosk.results.found', { n: 3 }). A missing key shows the key itself, so it is visible in the UI and caught by tests.
export function t(key, vars = {}, lang = current) {
  let v = own(lang, key) ?? own('uz', key) ?? key;
  if (typeof v === 'object') v = v[new Intl.PluralRules(lang).select(vars.n)] ?? v.many;
  return fill(v, vars);
}

// Server error text: vars that are dictionary keys (a field name, "common.size_one") and products ({ name, name_ru })
// are shown in the same language.
export function errorText(lang, key, vars = {}) {
  const local = Object.fromEntries(Object.entries(vars).map(([k, v]) => [k,
    typeof v === 'string' && own('uz', v) !== undefined ? t(v, {}, lang) : v && typeof v === 'object' ? productName(v, lang) : v]));
  return t(key, local, lang);
}

export const productName = (p, lang = current) => (lang === 'ru' && p.name_ru) || p.name;
export const colorName = (c, lang = current) => (lang === 'ru' && c && Object.hasOwn(COLORS_RU, c.toLowerCase()) && COLORS_RU[c.toLowerCase()]) || c;

// Numbers and times look the same in both languages (space-grouped so'm, dd.mm, 24 h), always in Tashkent time.
const NUM = new Intl.NumberFormat('ru-RU');
export const fmt = {
  num: (n) => NUM.format(n),
  som: (n, lang = current) => `${NUM.format(n)} ${t('common.som', {}, lang)}`,
  time: (iso) => new Date(iso).toLocaleTimeString('ru-RU', { timeZone: TZ, hour: '2-digit', minute: '2-digit' }),
  date: (iso) => new Date(iso).toLocaleDateString('ru-RU', { timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric' }),
  dateTime: (iso) => new Date(iso).toLocaleString('ru-RU', { timeZone: TZ, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }),
  countdown: (ms) => { const s = Math.max(0, Math.ceil(ms / 1000)); return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`; }, // 14:59
};

// --- Browser only below. The choice is remembered per device; the kiosk resets it to uz on idle.
const saved = () => {
  try { return localStorage.getItem(KEY); } catch { return null; }
};
export function setLang(lang, { remember = true } = {}) {
  current = LANGS.includes(lang) ? lang : 'uz';
  if (remember) try { localStorage.setItem(KEY, current); } catch {}
  document.documentElement.lang = current;
  translate(document);
  return current;
}
export const initLang = () => setLang(saved(), { remember: false });

// Static markup: data-i18n="key" sets the text; data-i18n-aria-label / -title / -placeholder set those attributes.
const ATTRS = ['aria-label', 'title', 'placeholder'];
export function translate(root) {
  for (const e of root.querySelectorAll('[data-i18n]')) e.textContent = t(e.dataset.i18n);
  for (const a of ATTRS) for (const e of root.querySelectorAll(`[data-i18n-${a}]`)) e.setAttribute(a, t(e.getAttribute(`data-i18n-${a}`)));
}

// Two pressed-state chips, each language named in itself (short: "UZ"/"RU", full name as the accessible name).
// onChange runs after the switch.
export function langSwitch(onChange, { short = false } = {}) {
  const box = document.createElement('div');
  box.className = 'lang-switch';
  box.setAttribute('role', 'group');
  box.setAttribute('data-i18n-aria-label', 'common.lang');
  box.setAttribute('aria-label', t('common.lang'));
  const sync = () => box.querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.lang === current)));
  for (const l of LANGS) {
    const name = t(`lang.${l}`, {}, l);
    const b = Object.assign(document.createElement('button'), { type: 'button', className: 'chip', lang: l, textContent: short ? l.toUpperCase() : name });
    if (short) b.setAttribute('aria-label', b.title = name);
    b.onclick = () => {
      if (l === current) return;
      setLang(l);
      sync();
      onChange?.(l);
    };
    box.append(b);
  }
  sync();
  box.sync = sync;
  return box;
}
